function* take<T>(source: Iterable<T>, n: number): Generator<T> {
  let i = 0;
  for (const item of source) {
    if (i++ >= n) return;        // ends the sequence early
    yield item;                  // item: T, resume on next()
  }
}

for (const x of take([1, 2, 3, 4], 2)) console.log(x);   // 1, 2

