async function* pages(url: string): AsyncGenerator<Item[]> {
  let next: string | undefined = url;
  while (next) {
    const res = await fetch(next);       // awaited per element
    const body: Page = await res.json();
    yield body.items;                    // typed one page per pull
    next = body.next;
  }
}

for await (const page of pages('/api/items')) console.log(page.length);
